6	struct SnapshotDecodeError: Error {
7	    let message: String
8	}
9	
10	// MARK: - Minimal strict JSON parser
11	//
12	// JSONSerialization is not strict enough for snapshot validation (it accepts
13	// duplicate keys, non-string fragments, and trailing garbage in some modes),
14	// so the snapshot format is validated with this small grammar-faithful
15	// parser instead.
16	
17	enum JSONValue {
18	    case null
19	    case bool(Bool)
20	    case number(String)                    // raw lexeme; grammar already validated
21	    case string(String)
22	    case array([JSONValue])
23	    case object([(String, JSONValue)])     // preserves member order and duplicates
24	}
25	
26	private struct JSONParser {
27	    private let scalars: [Unicode.Scalar]
28	    private var index = 0
29	
30	    init(_ text: String) {
31	        self.scalars = Array(text.unicodeScalars)
32	    }
33	
34	    static func parse(_ text: String) throws -> JSONValue {
35	        var parser = JSONParser(text)
36	        let value = try parser.parseValue()
37	        parser.skipWhitespace()
38	        guard parser.atEnd else {
39	            throw SnapshotDecodeError(message: "trailing content after JSON value")
40	        }
41	        return value
42	    }
43	
44	    private var atEnd: Bool { index >= scalars.count }
45	    private var current: Unicode.Scalar { scalars[index] }
46	
47	    private mutating func skipWhitespace() {
48	        while index < scalars.count {
49	            switch scalars[index] {
50	            case " ", "\t", "\n", "\r":
51	                index += 1
52	            default:
53	                return
54	            }
55	        }
56	    }
57	
58	    private mutating func parseValue() throws -> JSONValue {
59	        skipWhitespace()
60	        if atEnd { throw SnapshotDecodeError(message: "unexpected end of input") }
61	        switch current {
62	        case "{": return .object(try parseObject())
63	        case "[": return .array(try parseArray())
64	        case "\"": return .string(try parseString())
65	        case "t", "f": return try parseBool()
66	        case "n":
67	            try consumeLiteral("null")
68	            return .null
69	        default:
70	            if current == "-" || ("0"..."9").contains(current) {
71	                return .number(try parseNumber())
72	            }
73	            throw SnapshotDecodeError(message: "unexpected character in JSON")
74	        }
75	    }
76	
77	    private mutating func consumeLiteral(_ literal: String) throws {
78	        for scalar in literal.unicodeScalars {
79	            guard index < scalars.count, scalars[index] == scalar else {
80	                throw SnapshotDecodeError(message: "invalid JSON literal")
81	            }
82	            index += 1
83	        }
84	    }
85	
86	    private mutating func parseBool() throws -> JSONValue {
87	        if current == "t" {
88	            try consumeLiteral("true")
89	            return .bool(true)
90	        }
91	        try consumeLiteral("false")
92	        return .bool(false)
93	    }
94	
95	    private mutating func parseObject() throws -> [(String, JSONValue)] {
96	        index += 1 // "{"
97	        var members: [(String, JSONValue)] = []
98	        skipWhitespace()
99	        if !atEnd, current == "}" {
100	            index += 1
101	            return members
102	        }
103	        while true {
104	            skipWhitespace()
105	            if atEnd || current != "\"" {
106	                throw SnapshotDecodeError(message: "expected string key in object")
107	            }
108	            let key = try parseString()
109	            skipWhitespace()
110	            if atEnd || current != ":" {
111	                throw SnapshotDecodeError(message: "expected ':' after object key")
112	            }
113	            index += 1
114	            let value = try parseValue()
115	            members.append((key, value))
116	            skipWhitespace()
117	            if atEnd { throw SnapshotDecodeError(message: "unterminated object") }
118	            switch current {
119	            case ",":
120	                index += 1
121	                skipWhitespace()
122	                if atEnd || current != "\"" {
123	                    throw SnapshotDecodeError(message: "trailing comma in object")
124	                }
125	            case "}":
126	                index += 1
127	                return members
128	            default:
129	                throw SnapshotDecodeError(message: "expected ',' or '}' in object")
130	            }
131	        }
132	    }
133	
134	    private mutating func parseArray() throws -> [JSONValue] {
135	        index += 1 // "["
136	        var items: [JSONValue] = []
137	        skipWhitespace()
138	        if !atEnd, current == "]" {
139	            index += 1
140	            return items
141	        }
142	        while true {
143	            try items.append(parseValue())
144	            skipWhitespace()
145	            if atEnd { throw SnapshotDecodeError(message: "unterminated array") }
146	            switch current {
147	            case ",":
148	                index += 1
149	                skipWhitespace()
150	                if atEnd || current == "]" {
151	                    throw SnapshotDecodeError(message: "trailing comma in array")
152	                }
153	            case "]":
154	                index += 1
155	                return items
156	            default:
157	                throw SnapshotDecodeError(message: "expected ',' or ']' in array")
158	            }
159	        }
160	    }
161	
162	    private mutating func parseString() throws -> String {
163	        index += 1 // opening quote
164	        var output = String.UnicodeScalarView()
165	        while index < scalars.count {
166	            let scalar = scalars[index]
167	            switch scalar {
168	            case "\"":
169	                index += 1
170	                return String(output)
171	            case "\\":
172	                index += 1
173	                if atEnd { throw SnapshotDecodeError(message: "unterminated escape sequence") }
174	                switch scalars[index] {
175	                case "\"": output.append("\""); index += 1
176	                case "\\": output.append("\\"); index += 1
177	                case "/": output.append("/"); index += 1
178	                case "b": output.append("\u{08}"); index += 1
179	                case "f": output.append("\u{0C}"); index += 1
180	                case "n": output.append("\n"); index += 1
181	                case "r": output.append("\r"); index += 1
182	                case "t": output.append("\t"); index += 1
183	                case "u":
184	                    let codepoint = try parseUnicodeEscape()
185	                    switch codepoint {
186	                    case 0xD800...0xDBFF:
187	                        // A high surrogate must be immediately followed by
188	                        // an escaped low surrogate; lone surrogates are invalid.
189	                        guard index + 1 < scalars.count,
190	                              scalars[index] == "\\", scalars[index + 1] == "u"
191	                        else {
192	                            throw SnapshotDecodeError(message: "lone high surrogate in string")
193	                        }
194	                        index += 1 // point at the second 'u'
195	                        let low = try parseUnicodeEscape()
196	                        guard (0xDC00...0xDFFF).contains(low) else {
197	                            throw SnapshotDecodeError(message: "invalid surrogate pair in string")
198	                        }
199	                        let combined = 0x10000
200	                            + ((codepoint - 0xD800) << 10)
201	                            + (low - 0xDC00)
202	                        output.append(Unicode.Scalar(combined)!)
203	                    case 0xDC00...0xDFFF:
204	                        throw SnapshotDecodeError(message: "lone low surrogate in string")
205	                    default:
206	                        guard let decoded = Unicode.Scalar(codepoint) else {
207	                            throw SnapshotDecodeError(message: "invalid unicode escape")
208	                        }
209	                        output.append(decoded)
210	                    }
211	                default:
212	                    throw SnapshotDecodeError(message: "invalid escape sequence")
213	                }
214	            case "\u{00}"..."\u{1F}":
215	                throw SnapshotDecodeError(message: "unescaped control character in string")
216	            default:
217	                output.append(scalar)
218	                index += 1
219	            }
220	        }
221	        throw SnapshotDecodeError(message: "unterminated string")
222	    }
223	
224	    /// Called with `index` pointing at the 'u' of a `\uXXXX` escape; leaves
225	    /// `index` right after the fourth hex digit.
226	    private mutating func parseUnicodeEscape() throws -> UInt32 {
227	        index += 1 // past 'u'
228	        guard index + 4 <= scalars.count else {
229	            throw SnapshotDecodeError(message: "incomplete unicode escape")
230	        }
231	        var value: UInt32 = 0
232	        for _ in 0..<4 {
233	            let scalar = scalars[index]
234	            let digit: UInt32
235	            switch scalar {
236	            case "0"..."9":
237	                digit = UInt32(scalar.value - Unicode.Scalar("0").value)
238	            case "a"..."f":
239	                digit = UInt32(scalar.value - Unicode.Scalar("a").value) + 10
240	            case "A"..."F":
241	                digit = UInt32(scalar.value - Unicode.Scalar("A").value) + 10
242	            default:
243	                throw SnapshotDecodeError(message: "invalid hex digit in unicode escape")
244	            }
245	            value = value * 16 + digit
246	            index += 1
247	        }
248	        return value
249	    }
250	
251	    private mutating func parseNumber() throws -> String {
252	        let start = index
253	        if current == "-" { index += 1 }
254	        guard index < scalars.count else {
255	            throw SnapshotDecodeError(message: "invalid number")
256	        }
257	        if scalars[index] == "0" {
258	            index += 1
259	        } else if ("1"..."9").contains(scalars[index]) {
260	            index += 1
261	            while index < scalars.count, ("0"..."9").contains(scalars[index]) { index += 1 }
262	        } else {
263	            throw SnapshotDecodeError(message: "invalid number")
264	        }
265	        if index < scalars.count, scalars[index] == "." {
266	            index += 1
267	            guard index < scalars.count, ("0"..."9").contains(scalars[index]) else {
268	                throw SnapshotDecodeError(message: "invalid number fraction")
269	            }
270	            while index < scalars.count, ("0"..."9").contains(scalars[index]) { index += 1 }
271	        }
272	        if index < scalars.count, scalars[index] == "e" || scalars[index] == "E" {
273	            index += 1
274	            if index < scalars.count, scalars[index] == "+" || scalars[index] == "-" { index += 1 }
275	            guard index < scalars.count, ("0"..."9").contains(scalars[index]) else {
276	                throw SnapshotDecodeError(message: "invalid number exponent")
277	            }
278	            while index < scalars.count, ("0"..."9").contains(scalars[index]) { index += 1 }
279	        }
280	        return String(String.UnicodeScalarView(scalars[start..<index]))
281	    }
282	}
283	
284	// MARK: - Snapshot validation
285	
286	private let hexDigits = Set("0123456789abcdef".unicodeScalars)
287	
288	/// Validates a snapshot relative path: non-empty, `/`-separated, no leading
289	/// or trailing slash, no empty/`.`/`..` segments, no NUL bytes. Backslashes
290	/// are ordinary characters and Unicode is compared by code points without
291	/// normalization.
292	private func isValidRelativePath(_ path: String) -> Bool {
293	    let scalars = path.unicodeScalars
294	    guard let first = scalars.first, let last = scalars.last else { return false }
295	    guard first != "/", last != "/" else { return false }
296	    var segment = String.UnicodeScalarView()
297	    for scalar in scalars {
298	        if scalar == "/" {
299	            if segment.isEmpty || String(segment) == "." || String(segment) == ".." {
300	                return false
301	            }
302	            segment.removeAll(keepingCapacity: true)
303	        } else {
304	            if scalar == "\0" { return false }
305	            segment.append(scalar)
306	        }
307	    }
308	    return String(segment) != "." && String(segment) != ".."
309	}
310	
311	private func isValidSha256(_ value: String) -> Bool {
312	    value.unicodeScalars.count == 64 && value.unicodeScalars.allSatisfy { hexDigits.contains($0) }
313	}
314	
315	private func isValidTimestamp(_ value: String) -> Bool {
316	    let formatter = DateFormatter()
317	    formatter.locale = Locale(identifier: "en_US_POSIX")
318	    formatter.timeZone = TimeZone(identifier: "UTC")
319	    formatter.dateFormat = "yyyy-MM-dd'T'HH:mm:ss'Z'"
320	    formatter.isLenient = false
321	    guard let date = formatter.date(from: value) else { return false }
322	    return formatter.string(from: date) == value
323	}
324	
325	private func decodeFiles(_ value: JSONValue) throws -> [FileRecord] {
326	    guard case .array(let items) = value else {
327	        throw SnapshotDecodeError(message: "files must be an array")
328	    }
329	    var records: [FileRecord] = []
330	    var seenPaths = Set<String>()
331	    var previousPath: String?
332	    for item in items {
333	        guard case .object(let members) = item else {
334	            throw SnapshotDecodeError(message: "each file entry must be an object")
335	        }
336	        let keys = Set(members.map { $0.0 })
337	        guard members.count == 3, keys == ["path", "sha256", "size"] else {
338	            throw SnapshotDecodeError(message: "file entry has missing or extra fields")
339	        }
340	        let fields = Dictionary(members, uniquingKeysWith: { $1 })
341	
342	        guard case .string(let path) = fields["path"], isValidRelativePath(path) else {
343	            throw SnapshotDecodeError(message: "file entry has an invalid path")
344	        }
345	        guard case .string(let sha256) = fields["sha256"], isValidSha256(sha256) else {
346	            throw SnapshotDecodeError(message: "file entry has an invalid sha256")
347	        }
348	        guard case .number(let sizeLexeme) = fields["size"],
349	              sizeLexeme.first != "-",
350	              let size = Int64(sizeLexeme, radix: 10), size >= 0
351	        else {
352	            throw SnapshotDecodeError(message: "file entry has an invalid size")
353	        }
354	
355	        if seenPaths.contains(path) {
356	            throw SnapshotDecodeError(message: "duplicate path in files: \(path)")
357	        }
358	        if let previous = previousPath, !utf8Precedes(previous, path) {
359	            throw SnapshotDecodeError(message: "file entries are not sorted by path")
360	        }
361	        seenPaths.insert(path)
362	        previousPath = path
363	        records.append(FileRecord(path: path, sha256: sha256, size: size))
364	    }
365	    return records
366	}
367	
368	/// Parses and strictly validates a snapshot, returning its file records.
369	/// Never repairs the file; any problem throws `SnapshotDecodeError`.
370	private func decodeSnapshot(_ data: Data) throws -> [FileRecord] {
371	    guard let text = String(data: data, encoding: .utf8) else {
372	        throw SnapshotDecodeError(message: "snapshot is not valid UTF-8")
373	    }
374	    let value = try JSONParser.parse(text)
375	    guard case .object(let members) = value else {
376	        throw SnapshotDecodeError(message: "snapshot root must be an object")
377	    }
378	    let keys = Set(members.map { $0.0 })
379	    guard members.count == 3, keys == ["version", "capturedAt", "files"] else {
380	        throw SnapshotDecodeError(message: "snapshot has missing or extra fields")
381	    }
382	    let fields = Dictionary(members, uniquingKeysWith: { $1 })
383	
384	    guard case .number(let versionLexeme) = fields["version"], versionLexeme == "1" else {
385	        throw SnapshotDecodeError(message: "unsupported snapshot version")
386	    }
387	    guard case .string(let capturedAt) = fields["capturedAt"], isValidTimestamp(capturedAt) else {
388	        throw SnapshotDecodeError(message: "invalid capturedAt timestamp")
389	    }
390	    return try decodeFiles(fields["files"]!)
391	}
392	
393	// MARK: - Snapshot rendering
394	
395	private func utcTimestamp() -> String {
396	    let formatter = DateFormatter()
397	    formatter.locale = Locale(identifier: "en_US_POSIX")
398	    formatter.timeZone = TimeZone(identifier: "UTC")
399	    formatter.dateFormat = "yyyy-MM-dd'T'HH:mm:ss'Z'"
400	    return formatter.string(from: Date())
401	}
402	
403	private func renderSnapshot(records: [FileRecord], capturedAt: String) -> String {
404	    var output = "{\"version\":1,\"capturedAt\":\(jsonEscape(capturedAt)),\"files\":["
405	    output += records.map { record in
406	        "{\"path\":\(jsonEscape(record.path)),"
407	            + "\"sha256\":\(jsonEscape(record.sha256)),"
408	            + "\"size\":\(record.size)}"
409	    }.joined(separator: ",")
410	    output += "]}"
411	    return output
412	}
413	
414	// MARK: - Helpers
415	
416	private func reportCollectionErrors(_ errors: [CompareError]) {
417	    let ordered = errors.enumerated().sorted { a, b in
418	        a.element.path == b.element.path
419	            ? a.offset < b.offset
420	            : utf8Precedes(a.element.path, b.element.path)
421	    }
422	    var text = ""
423	    for error in ordered {
424	        text += "error: \(error.element.path): \(error.element.message)\n"
425	    }
426	    writeStderr(text)
427	}
428	
429	private func isPath(_ path: String, inside ancestor: String) -> Bool {
430	    let ancestorComponents = (ancestor as NSString).pathComponents
431	    let pathComponents = (path as NSString).pathComponents
432	    return pathComponents.count >= ancestorComponents.count
433	        && Array(pathComponents.prefix(ancestorComponents.count)) == ancestorComponents
434	}
435	
436	private enum PublishError: Error {
437	    case destinationExists
438	    case io(String)
439	}
440	
441	/// Writes `json` to a staging file in the destination's own directory and
442	/// publishes it with `link(2)`, which fails with EEXIST instead of ever
443	/// overwriting an existing destination. The staging file is removed on every
444	/// failure path.
445	private func publishSnapshot(json: String, to snapshotPath: String) throws {
446	    let bytes = Data(json.utf8)
447	    let snapshotURL = URL(fileURLWithPath: snapshotPath)
448	    let parentPath = normalizedRoot(snapshotURL.deletingLastPathComponent().path)
449	    let tempName = String(
450	        format: ".macvault-snapshot.%d.%016llx.tmp",
451	        ProcessInfo.processInfo.processIdentifier,
452	        UInt64.random(in: 0...UInt64.max))
453	    let tempPath = (parentPath as NSString).appendingPathComponent(tempName)
454	
455	    let fd = open(tempPath, O_CREAT | O_EXCL | O_WRONLY, 0o644)
456	    guard fd >= 0 else {
457	        throw PublishError.io(
458	            "cannot create staging file: \(String(cString: strerror(errno)))")
459	    }
460	
461	    do {
462	        var offset = 0
463	        while offset < bytes.count {
464	            let written = bytes.withUnsafeBytes { rawBuffer -> Int in
465	                write(fd, rawBuffer.baseAddress!.advanced(by: offset), bytes.count - offset)
466	            }
467	            if written < 0 {
468	                if errno == EINTR { continue }
469	                throw PublishError.io("staging write failed: \(String(cString: strerror(errno)))")
470	            }
471	            offset += written
472	        }
473	        if fsync(fd) != 0 {
474	            throw PublishError.io("staging sync failed: \(String(cString: strerror(errno)))")
475	        }
476	        if close(fd) != 0 {
477	            throw PublishError.io("staging close failed: \(String(cString: strerror(errno)))")
478	        }
479	    } catch {
480	        close(fd)
481	        unlink(tempPath)
482	        throw error
483	    }
484	
485	    if link(tempPath, snapshotPath) != 0 {
486	        if errno == EEXIST {
487	            unlink(tempPath)
488	            throw PublishError.destinationExists
489	        }
490	        let message = "cannot publish snapshot: \(String(cString: strerror(errno)))"
491	        unlink(tempPath)
492	        throw PublishError.io(message)
493	    }
494	    unlink(tempPath)
495	}
496	
497	// MARK: - `snapshot`
498	
499	func runSnapshot(sourcePath: String, snapshotPath: String) -> Int32 {
500	    let fileManager = FileManager.default
501	
502	    var sourceIsDirectory: ObjCBool = false
503	    guard fileManager.fileExists(atPath: sourcePath, isDirectory: &sourceIsDirectory),
504	          sourceIsDirectory.boolValue
505	    else {
506	        writeStderr("error: not an existing directory: \(sourcePath)\n")
507	        return 64
508	    }
509	
510	    let sourceRoot = normalizedRoot(sourcePath)
511	    let snapshotURL = URL(fileURLWithPath: snapshotPath)
512	    let resolvedParent = normalizedRoot(snapshotURL.deletingLastPathComponent().path)
513	    let resolvedSnapshot = (resolvedParent as NSString)
514	        .appendingPathComponent(snapshotURL.lastPathComponent)
515	    guard !isPath(resolvedSnapshot, inside: sourceRoot) else {
516	        writeStderr("error: SNAPSHOT must not be located inside SOURCE: \(snapshotPath)\n")
517	        return 64
518	    }
519	
520	    guard !fileManager.fileExists(atPath: snapshotPath) else {
521	        writeStderr("error: snapshot destination already exists: \(snapshotPath)\n")
522	        return 73
523	    }
524	
525	    var errors: [CompareError] = []
526	    let files = enumerateRegularFiles(root: sourceRoot, errors: &errors)
527	
528	    var records: [FileRecord] = []
529	    for relative in files.sorted(by: utf8Precedes) {
530	        switch hashFile(root: sourceRoot, relativePath: relative) {
531	        case .success(let record): records.append(record)
532	        case .failure(let error): errors.append(error)
533	        }
534	    }
535	
536	    guard errors.isEmpty else {
537	        reportCollectionErrors(errors)
538	        return 74
539	    }
540	
541	    let json = renderSnapshot(records: records, capturedAt: utcTimestamp())
542	    do {
543	        try publishSnapshot(json: json, to: snapshotPath)
544	    } catch PublishError.destinationExists {
545	        writeStderr("error: snapshot destination already exists: \(snapshotPath)\n")
546	        return 73
547	    } catch PublishError.io(let message) {
548	        writeStderr("error: \(message)\n")
549	        return 1
550	    } catch {
551	        writeStderr("error: \(error)\n")
552	        return 1
553	    }
554	    return 0
555	}
556	
557	// MARK: - `snapshot-diff`
558	
559	func runSnapshotDiff(snapshotPath: String, currentPath: String) -> Int32 {
560	    let fileManager = FileManager.default
561	
562	    var currentIsDirectory: ObjCBool = false
563	    guard fileManager.fileExists(atPath: currentPath, isDirectory: &currentIsDirectory),
564	          currentIsDirectory.boolValue
565	    else {
566	        writeStderr("error: not an existing directory: \(currentPath)\n")
567	        return 64
568	    }
569	
570	    let snapshotData: Data
571	    do {
572	        snapshotData = try Data(contentsOf: URL(fileURLWithPath: snapshotPath))
573	    } catch {
574	        writeStderr("error: cannot read snapshot \(snapshotPath): \(error.localizedDescription)\n")
575	        return 65
576	    }
577	
578	    let snapshotRecords: [FileRecord]
579	    do {
580	        snapshotRecords = try decodeSnapshot(snapshotData)
581	    } catch let error as SnapshotDecodeError {
582	        writeStderr("error: invalid snapshot \(snapshotPath): \(error.message)\n")
583	        return 65
584	    } catch {
585	        writeStderr("error: invalid snapshot \(snapshotPath)\n")
586	        return 65
587	    }
588	
589	    let currentRoot = normalizedRoot(currentPath)
590	    var errors: [CompareError] = []
591	    let files = enumerateRegularFiles(root: currentRoot, errors: &errors)
592	
593	    var currentRecords: [FileRecord] = []
594	    for relative in files.sorted(by: utf8Precedes) {
595	        switch hashFile(root: currentRoot, relativePath: relative) {
596	        case .success(let record): currentRecords.append(record)
597	        case .failure(let error): errors.append(error)
598	        }
599	    }
600	
601	    guard errors.isEmpty else {
602	        reportCollectionErrors(errors)
603	        return 74
604	    }
605	
606	    let entries = sortEntries(computeDiff(
607	        oldRecords: snapshotRecords,
608	        newRecords: currentRecords))
609	    print(renderJSON(entries))
610	    return 0
611	}
